from pathlib import Path
import numpy as np,json,hashlib,struct
r=Path(__file__).resolve().parent;p=r/'data/case0.bin';data=p.read_bytes();n,steps,cold=struct.unpack_from('<iii',data);assert(n,steps,cold)==(500000,1,0)
v=np.frombuffer(data,dtype='<f8',offset=12).reshape(2,n,2);assert np.array_equal(v[0,:,0],v[1,:,0]);L=np.longdouble;u32=L(2)**-24;u64=L(2)**-53;u80=L(2)**-63
def g(n,u):return L(n)*u/(1-L(n)*u)
dx=L(float(1e-4));eps=L(float(8.85418782e-12));q=L(float(1.602176565e-19));domain=float(100*1e-4);weight=float(1e16*domain/n);factor=L(float(weight/float(1e-4)));lc=v[0,:,0].astype(L)/dx;i=np.floor(lc).astype(np.int64);d=lc-i;assert np.all((i>=0)&(i<100));s=np.zeros(101,dtype=L);counts=np.zeros(101,dtype=np.int64);np.add.at(s,i,1-d);np.add.at(s,i+1,d);np.add.at(counts,i,1);np.add.at(counts,i+1,1)
# Upperenclosure accountsforLongDouble evaluation/summation and sourceFP64logicalposition ops.
supper=s*(1+g(n,u80))+n*g(16,u80)*101;count_error=(counts.astype(L)+2)*u32/(1-(counts.astype(L)+2)*u32)*supper+u32*supper+n*g(16,u64)*101+counts.astype(L)*L(np.nextafter(np.float32(0),np.float32(1)))
factors=np.full(101,factor,dtype=L);factors[[0,100]]*=2;ideal=supper*factors;den_error=factors*count_error+(u32+g(8,u64))*(ideal+factors*count_error);rho_bound=2*abs(q)*den_error+g(8,u64)*abs(q)*(2*ideal+2*den_error)
j=np.arange(1,100,dtype=L);G=np.minimum(j[:,None],j[None,:])*(100-np.maximum(j[:,None],j[None,:]))/100*dx*dx/eps;phi_from_charge=G@rho_bound[1:100];lap_row=dx*dx*j*(100-j)/2;gamma_res=g(32,u64);maxlap=np.max(lap_row);feedback=maxlap*gamma_res*4/(dx*dx);assert feedback<1
# Stored source residual L2<1e-4 => each computedresidual<101e-4.
